-- State-wide geography support for Hamburg and Schleswig-Holstein.
-- Municipality source: Destatis GV100-derived municipality register (2022 snapshot),
-- reconciled with Statistik Nord's official changes: Hürup merger effective 2023-03-01,
-- and removal of the non-municipal forest districts Sachsenwald and Buchholz effective 2026-01-01.
-- Official references:
-- https://www.destatis.de/DE/Themen/Laender-Regionen/Regionales/Gemeindeverzeichnis/_inhalt.html
-- https://www.statistik-nord.de/zahlen-fakten/gebiet-flaeche/gebietsgliederung-schleswig-holstein
begin;
create table if not exists public.geo_areas (
  area_code text primary key,
  state_code text not null check (state_code in ('HH','SH')),
  parent_code text references public.geo_areas(area_code) deferrable initially deferred,
  area_type text not null check (area_type in ('state','county','independent_city','municipality','borough','neighborhood')),
  name text not null,
  official_code text,
  source_name text not null,
  source_vintage text not null,
  is_active boolean not null default true,
  updated_at timestamptz not null default now()
);
create index if not exists geo_areas_state_type_name_idx on public.geo_areas(state_code,area_type,name);
create index if not exists geo_areas_parent_idx on public.geo_areas(parent_code);
create index if not exists geo_areas_official_code_idx on public.geo_areas(official_code) where official_code is not null;
alter table public.search_profiles add column if not exists location_state_code text not null default 'HH', add column if not exists location_area_codes text[] not null default '{}'::text[];
alter table public.listings add column if not exists state_code text not null default 'HH', add column if not exists admin_region_code text, add column if not exists municipality_code text;
alter table public.search_profiles drop constraint if exists search_profiles_location_mode_check;
alter table public.search_profiles add constraint search_profiles_location_mode_check check (location_mode in ('all_hamburg','boroughs','neighborhoods','all_schleswig_holstein','schleswig_holstein_areas'));
values ('HH','HH',null,'state','Hamburg','02','Statistik Nord','2026-10-22',true),('SH','SH',null,'state','Schleswig-Holstein','01','Destatis / Statistik Nord','2026-01-01',true)
on conflict(area_code) do update set name=excluded.name,state_code=excluded.state_code,parent_code=excluded.parent_code,area_type=excluded.area_type,is_active=true,updated_at=now();
select 'HH-B-'||b.id::text,'HH','HH','borough',b.name,null,'Existing Hamburg geography catalog','2026-10-22',true from public.hamburg_boroughs b
on conflict(area_code) do update set name=excluded.name,parent_code=excluded.parent_code,is_active=true,updated_at=now();
select 'HH-N-'||n.id::text,'HH','HH-B-'||n.borough_id::text,'neighborhood',n.name,null,'Existing Hamburg geography catalog','2026-10-22',true from public.hamburg_neighborhoods n
on conflict(area_code) do update set name=excluded.name,parent_code=excluded.parent_code,is_active=true,updated_at=now();
on conflict(area_code) do update set name=excluded.name,parent_code=excluded.parent_code,area_type=excluded.area_type,official_code=excluded.official_code,is_active=true,updated_at=now();
on conflict(area_code) do update set name=excluded.name,parent_code=excluded.parent_code,area_type=excluded.area_type,official_code=excluded.official_code,source_name=excluded.source_name,source_vintage=excluded.source_vintage,is_active=true,updated_at=now();
create table if not exists public.geo_area_aliases (alias text not null,area_code text not null references public.geo_areas(area_code) on delete cascade,source_name text not null default 'manual',primary key(alias,area_code));
create index if not exists geo_area_aliases_alias_idx on public.geo_area_aliases(lower(alias));
alter table public.geo_areas enable row level security;
alter table public.geo_area_aliases enable row level security;
create or replace function app_private.save_search_profile_values(p_user uuid,p_values jsonb) returns uuid language plpgsql set search_path to '' as $function$
declare
 u public.bot_users%rowtype; v public.search_profiles%rowtype; v_id uuid; slot integer; types text[]; v_type text;
 v_min_rooms numeric; v_min_area numeric; v_furnished text; v_mode text; v_state_code text:='HH';
 v_boroughs text[]:='{}'::text[]; v_neighborhoods text[]:='{}'::text[]; v_districts text[]:='{}'::text[];
 v_location_area_codes text[]:='{}'::text[]; v_requested_area_codes text[]:='{}'::text[];
begin
 select * into u from public.bot_users where id=p_user and is_active for share;
 if not found then raise exception 'participant_unavailable'; end if;
 if jsonb_typeof(p_values)<>'object' or octet_length(p_values::text)>24000 then raise exception 'invalid_profile'; end if;
 slot:=coalesce((p_values->>'profile_slot')::integer,1);
 if slot<1 or slot>(case when app_private.user_is_premium(p_user) then 4 else 1 end) then raise exception 'profile_slot_not_allowed'; end if;
 if coalesce(jsonb_typeof(p_values->'property_types'),'')<>'array' or jsonb_array_length(p_values->'property_types')<>1 then raise exception 'invalid_property_types'; end if;
 v_type:=p_values#>>'{property_types,0}';
 if v_type not in ('Wohnung','Haus','WG','Tauschwohnung') then raise exception 'invalid_property_types'; end if;
 types:=array[v_type];
 if (p_values->>'max_warm_rent') is null or (p_values->>'max_warm_rent')::numeric not between 100 and 5000 then raise exception 'invalid_profile_limits'; end if;
 v_min_rooms:=(p_values->>'min_rooms')::numeric; v_min_area:=(p_values->>'min_area_sqm')::numeric;
 if v_min_rooms is null or v_min_rooms not between 1 and 20 or v_min_area is null or v_min_area not between 0 and 1000 then raise exception 'invalid_profile_limits'; end if;
 v_mode:=p_values->>'location_mode';
 if v_mode not in ('all_hamburg','boroughs','neighborhoods','all_schleswig_holstein','schleswig_holstein_areas') or v_mode is null then raise exception 'invalid_profile_location'; end if;
 if v_mode='boroughs' then
  if coalesce(jsonb_typeof(p_values->'boroughs'),'')<>'array' or jsonb_array_length(p_values->'boroughs')=0 then raise exception 'invalid_profile_location'; end if;
  select coalesce(array_agg(value order by value),'{}'::text[]) into v_boroughs from jsonb_array_elements_text(p_values->'boroughs') t(value);
  if (select count(*) from public.hamburg_boroughs where name=any(v_boroughs))<>cardinality(v_boroughs) then raise exception 'invalid_profile_location'; end if;
  select coalesce(array_agg(hn.name order by hn.id),'{}'::text[]) into v_districts from public.hamburg_neighborhoods hn join public.hamburg_boroughs hb on hb.id=hn.borough_id where hb.name=any(v_boroughs);
 elsif v_mode='neighborhoods' then
  if coalesce(jsonb_typeof(p_values->'neighborhoods'),'')<>'array' or jsonb_array_length(p_values->'neighborhoods')=0 then raise exception 'invalid_profile_location'; end if;
  select coalesce(array_agg(value order by value),'{}'::text[]) into v_neighborhoods from jsonb_array_elements_text(p_values->'neighborhoods') t(value);
  if (select count(*) from public.hamburg_neighborhoods where name=any(v_neighborhoods))<>cardinality(v_neighborhoods) then raise exception 'invalid_profile_location'; end if;
  v_districts:=v_neighborhoods;
  select coalesce(array_agg(distinct hb.name order by hb.name),'{}'::text[]) into v_boroughs from public.hamburg_neighborhoods hn join public.hamburg_boroughs hb on hb.id=hn.borough_id where hn.name=any(v_neighborhoods);
 elsif v_mode='all_schleswig_holstein' then
  v_state_code:='SH'; v_districts:=array['Ganz Schleswig-Holstein']::text[];
 elsif v_mode='schleswig_holstein_areas' then
  v_state_code:='SH';
  if coalesce(jsonb_typeof(p_values->'location_area_codes'),'')<>'array' or jsonb_array_length(p_values->'location_area_codes')=0 then raise exception 'invalid_profile_location'; end if;
  select coalesce(array_agg(distinct value order by value),'{}'::text[]) into v_requested_area_codes from jsonb_array_elements_text(p_values->'location_area_codes') t(value);
  if cardinality(v_requested_area_codes)=0 or (select count(*) from public.geo_areas where area_code=any(v_requested_area_codes) and state_code='SH' and area_type in ('county','independent_city','municipality'))<>cardinality(v_requested_area_codes) then raise exception 'invalid_profile_location'; end if;
  select coalesce(array_agg(g.area_code order by g.area_code),'{}'::text[]) into v_location_area_codes from public.geo_areas g where g.area_code=any(v_requested_area_codes)
   and not exists(select 1 from public.geo_areas parent where parent.area_code=any(v_requested_area_codes) and g.parent_code=parent.area_code);
  if cardinality(v_location_area_codes)=0 then raise exception 'invalid_profile_location'; end if;
  select coalesce(array_agg(g.name order by g.name),'{}'::text[]) into v_districts from public.geo_areas g where g.area_code=any(v_location_area_codes);
 else v_districts:=array['Ganz Hamburg']::text[];
 end if;
 select * into v from public.search_profiles where user_id=p_user and profile_slot=slot for update;
 v_furnished:=case when p_values?'furnished_preference' then case p_values->>'furnished_preference' when 'furnished' then 'yes' when 'unfurnished' then 'no' when 'yes' then 'yes' when 'no' then 'no' else 'any' end else coalesce(v.furnished_preference,'any') end;
 values(p_user,slot,coalesce(v.name,case when slot=1 then 'Meine Suche' else 'Meine Suche '||slot end),types,v_mode,v_state_code,v_location_area_codes,v_districts,v_boroughs,v_neighborhoods,(p_values->>'max_warm_rent')::numeric,v_min_rooms,v_min_area,0,
 case when p_values?'wbs_only' then (p_values->>'wbs_only')::boolean else coalesce(v.wbs_only,false) end,v_furnished,
 case when p_values?'require_known_warm_rent' then (p_values->>'require_known_warm_rent')::boolean else coalesce(v.require_known_warm_rent,false) end,
 case when p_values?'max_deposit' and nullif(p_values->>'max_deposit','') is not null then greatest(0,(p_values->>'max_deposit')::numeric) else v.max_deposit end,now())
 on conflict(user_id,profile_slot) do update set property_types=excluded.property_types,location_mode=excluded.location_mode,location_state_code=excluded.location_state_code,location_area_codes=excluded.location_area_codes,districts=excluded.districts,boroughs=excluded.boroughs,neighborhoods=excluded.neighborhoods,max_warm_rent=excluded.max_warm_rent,min_rooms=excluded.min_rooms,min_area_sqm=excluded.min_area_sqm,min_room_area_sqm=excluded.min_room_area_sqm,wbs_only=excluded.wbs_only,furnished_preference=excluded.furnished_preference,require_known_warm_rent=excluded.require_known_warm_rent,max_deposit=excluded.max_deposit,updated_at=now()
 returning id into v_id;
 return v_id;
end
$function$;

create or replace function app_private.matches_property_filters(p public.search_profiles,l public.listings) returns boolean language plpgsql stable set search_path to '' as $function$
declare c jsonb; v_category text; v_price numeric; v_rooms numeric; v_area numeric; v_haystack text; v_location_ok boolean:=false;
begin
 if cardinality(p.property_types)<>1 or p.property_types[1] not in ('Wohnung','Haus','WG','Tauschwohnung') then return false; end if;
 if exists(select 1 from public.sources s where s.id=l.source_id and s.source_type='Baugenossenschaft') then v_category:='Wohnung';
 else c:=app_private.classify_listing_category(l.source_id,l.property_type,l.property_kind,l.offer_mode,l.title,l.raw);v_category:=c->>'category';end if;
 if v_category is null or v_category<>p.property_types[1] then return false; end if;
 if p.max_warm_rent is not null then v_price:=nullif(l.warm_rent,0);if v_price is not null and v_price>p.max_warm_rent then return false;end if;
  if v_price is null and coalesce(p.require_known_warm_rent,false)=false and coalesce(nullif(l.cold_rent,0),0)>p.max_warm_rent then return false;end if;end if;
 if coalesce(p.require_known_warm_rent,false) and coalesce(l.warm_rent,0)<=0 then return false;end if;
 if p.max_deposit is not null and (l.deposit is null or l.deposit>p.max_deposit) then return false;end if;
 if p.wbs_only and l.wbs_required is distinct from true then return false;end if;
 if p.furnished_preference='yes' and l.furnished is distinct from true then return false;elsif p.furnished_preference='no' and l.furnished is distinct from false then return false;end if;
 v_rooms:=nullif(l.rooms,0);v_area:=nullif(l.area_sqm,0);
 if coalesce(p.min_rooms,0)>0 and v_rooms is not null and v_rooms<p.min_rooms then return false;end if;
 if coalesce(p.min_area_sqm,0)>0 and v_area is not null and v_area<p.min_area_sqm then return false;end if;
 v_haystack:=lower(concat_ws(' ',l.district,l.address,l.title,l.raw::text));
 v_location_ok:=(p.location_mode='all_hamburg' and coalesce(l.state_code,'HH')='HH')
  or (p.location_mode='boroughs' and coalesce(l.state_code,'HH')='HH' and coalesce(cardinality(p.boroughs),0)>=7)
  or (p.location_mode='neighborhoods' and coalesce(l.state_code,'HH')='HH' and exists(select 1 from unnest(p.neighborhoods) n where v_haystack like '%'||lower(n)||'%'))
  or (p.location_mode='boroughs' and coalesce(l.state_code,'HH')='HH' and exists(select 1 from public.hamburg_neighborhoods hn join public.hamburg_boroughs hb on hb.id=hn.borough_id where hb.name=any(p.boroughs) and v_haystack like '%'||lower(hn.name)||'%'))
  or (p.location_mode='all_schleswig_holstein' and l.state_code='SH')
  or (p.location_mode='schleswig_holstein_areas' and l.state_code='SH' and (l.admin_region_code=any(coalesce(p.location_area_codes,'{}'::text[])) or l.municipality_code=any(coalesce(p.location_area_codes,'{}'::text[]))))
  or (p.location_mode in ('all_hamburg','boroughs','neighborhoods') and coalesce(l.state_code,'HH')='HH' and coalesce(cardinality(p.districts),0)>0 and ('Ganz Hamburg'=any(p.districts) or exists(select 1 from unnest(p.districts) d where v_haystack like '%'||lower(d)||'%')));
 return coalesce(v_location_ok,false);
end
$function$;
create index if not exists listings_state_region_idx on public.listings(state_code,admin_region_code);
create index if not exists listings_municipality_code_idx on public.listings(municipality_code) where municipality_code is not null;
comment on table public.geo_areas is 'Canonical geographic hierarchy for housing search. Schleswig-Holstein municipality list reconciled with official 2023/2026 administrative changes.';
comment on column public.listings.state_code is 'Canonical German state scope used by search matching; legacy listings are HH by default.';
comment on column public.listings.admin_region_code is 'Canonical five-digit AGS-equivalent region code for county-level search.';
comment on column public.listings.municipality_code is 'Canonical eight-digit AGS for a verified municipality.';
comment on column public.search_profiles.location_area_codes is 'Selected canonical geography codes for schleswig_holstein_areas search profiles.';

-- Persist and validate canonical state/region/municipality metadata from source adapters.
CREATE OR REPLACE FUNCTION public.ingest_listing_batch_v3(p_source_id smallint, p_rows jsonb, p_presence_epoch timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  result jsonb;
  allowed_keys constant text[] := array[
    'source_id','source_listing_key','external_id','canonical_url','title','address',
    'district','postal_code','city','state_code','admin_region_code','municipality_code','warm_rent','cold_rent','additional_costs',
    'operating_costs','heating_costs','deposit','deposit_text','rooms','area_sqm',
    'available_from','property_type','furnished','wbs_required','image_url',
    'cross_source_hash','raw','fresh_delivery_eligible','last_seen_at','is_active'
  ];
begin
  if p_source_id is null or p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'source and listing array are required' using errcode='22023';
  end if;
  if jsonb_array_length(p_rows) > 100 then
    raise exception 'listing batch exceeds 100 rows' using errcode='22023';
  end if;
  if jsonb_array_length(p_rows) = 0 then
    return jsonb_build_object('seen',0,'fresh',0,'changed',0,'touched',0);
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) x
    where jsonb_typeof(x) <> 'object'
       or (x->>'source_id')::smallint is distinct from p_source_id
       or coalesce(length(btrim(x->>'source_listing_key')),0) not between 1 and 500
       or coalesce(jsonb_typeof(x->'raw'),'null') <> 'object'
       or (x->>'last_seen_at')::timestamptz is null
       or (x->>'is_active')::boolean is distinct from true
       or coalesce(x->>'state_code','HH') not in ('HH','SH')
       or ((x->>'state_code')='SH' and not exists (
         select 1 from public.geo_areas municipality
         where municipality.area_code=x->>'municipality_code'
           and municipality.parent_code=x->>'admin_region_code'
           and municipality.state_code='SH' and municipality.area_type='municipality'
       ))
       or exists (
         select 1 from jsonb_object_keys(x) k
         where not k = any(allowed_keys)
       )
  ) or (
    select count(*) <> count(distinct x->>'source_listing_key')
    from jsonb_array_elements(p_rows) x
  ) then
    raise exception 'invalid listing batch, source mismatch or duplicate key' using errcode='22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(913247, p_source_id::integer);

  -- Unchanged observations do not take a write-producing row lock.

  with input as materialized (
    select
      jsonb_populate_record(null::public.listings, x) as r,
      pg_catalog.sha256(
        pg_catalog.convert_to((x - 'last_seen_at')::text,'UTF8')
      ) as fingerprint
    from jsonb_array_elements(p_rows) x
  ),
  classified as materialized (
    select
      i.r,
      i.fingerprint,
      l.id,
      coalesce(l.ingest_fingerprint = i.fingerprint and l.is_active,false) as unchanged
    from input i
    left join public.listings l
      on l.source_id = p_source_id
     and l.source_listing_key = (i.r).source_listing_key
  ),
  touched as (
    update public.listings l
    set last_seen_at = greatest(l.last_seen_at,(c.r).last_seen_at)
    from classified c
    where c.unchanged
      and l.id = c.id
      and l.is_active = true
      and l.ingest_fingerprint = c.fingerprint
      and (
        (
          p_presence_epoch is not null
          and (l.last_seen_at is null or l.last_seen_at < p_presence_epoch)
        )
        or
        (
          p_presence_epoch is null
          and (
            l.last_seen_at is null
            or l.last_seen_at < (c.r).last_seen_at -
              case when p_source_id in (1,3)
                         and (c.r).fresh_delivery_eligible
                         and l.first_seen_at >= statement_timestamp() - interval '24 hours'
                   then interval '9 minutes'
                   else interval '30 minutes' end
          )
        )
      )
    returning l.id
  ),
  written as (
      source_id,source_listing_key,external_id,canonical_url,title,address,district,
      postal_code,city,state_code,admin_region_code,municipality_code,warm_rent,cold_rent,additional_costs,operating_costs,
      heating_costs,deposit,deposit_text,rooms,area_sqm,available_from,property_type,
      furnished,wbs_required,image_url,cross_source_hash,raw,fresh_delivery_eligible,
      last_seen_at,is_active,ingest_fingerprint
    )
    select
      (c.r).source_id,(c.r).source_listing_key,(c.r).external_id,(c.r).canonical_url,
      (c.r).title,(c.r).address,(c.r).district,(c.r).postal_code,(c.r).city,
      (c.r).state_code,(c.r).admin_region_code,(c.r).municipality_code,(c.r).warm_rent,(c.r).cold_rent,(c.r).additional_costs,(c.r).operating_costs,
      (c.r).heating_costs,(c.r).deposit,(c.r).deposit_text,(c.r).rooms,(c.r).area_sqm,
      (c.r).available_from,(c.r).property_type,(c.r).furnished,(c.r).wbs_required,
      (c.r).image_url,(c.r).cross_source_hash,(c.r).raw,(c.r).fresh_delivery_eligible,
      (c.r).last_seen_at,(c.r).is_active,c.fingerprint
    from classified c
    where not c.unchanged
    on conflict (source_id,source_listing_key) do update set
      external_id = excluded.external_id,
      canonical_url = excluded.canonical_url,
      title = excluded.title,
      address = excluded.address,
      district = excluded.district,
      postal_code = excluded.postal_code,
      city = excluded.city,
      state_code = excluded.state_code,
      admin_region_code = excluded.admin_region_code,
      municipality_code = excluded.municipality_code,
      warm_rent = excluded.warm_rent,
      cold_rent = excluded.cold_rent,
      additional_costs = excluded.additional_costs,
      operating_costs = excluded.operating_costs,
      heating_costs = excluded.heating_costs,
      deposit = excluded.deposit,
      deposit_text = excluded.deposit_text,
      rooms = excluded.rooms,
      area_sqm = excluded.area_sqm,
      available_from = excluded.available_from,
      property_type = excluded.property_type,
      furnished = excluded.furnished,
      wbs_required = excluded.wbs_required,
      image_url = excluded.image_url,
      cross_source_hash = excluded.cross_source_hash,
      raw = excluded.raw,
      fresh_delivery_eligible = excluded.fresh_delivery_eligible,
      last_seen_at = greatest(l.last_seen_at,excluded.last_seen_at),
      is_active = excluded.is_active,
      ingest_fingerprint = excluded.ingest_fingerprint
    returning (xmax = 0) as inserted
  )
  select jsonb_build_object(
    'seen',(select count(*) from input),
    'fresh',(select count(*) from written where inserted),
    'changed',(select count(*) from written),
    'touched',(select count(*) from touched)
  )
  into result;

  return result;
end;
$function$

-- Add a separate state-wide WG-Gesucht lane; keep the existing Hamburg lane intact.
  source_id,priority,label,connector_kind,config,enabled,evidence_tier,connector_role,enumerable,shadow_only
)
select
  6,4,'Schleswig-Holstein public search','html_discovery',
  jsonb_build_object(
    'url','https://www.wg-gesucht.de/wohnungen-in-Schleswig-Holstein.0.2.1.0.html',
    'freshness_mode','newest_first',
    'region_state_code','SH'
  ),
  true,'K2','primary',false,false
where exists(select 1 from public.sources where id=6)
  and not exists(select 1 from public.source_connectors where source_id=6 and priority=4);

commit;
